#!/usr/bin/env bash
# ReNOVU feature-survival guards: run after every upstream merge (see RENOVU_FEATURES.md).
# Usage: bash feature-guards.sh [now|post|all]   (run from repo root)
#   now  = must pass before AND after the merge;  post = target state after resolution;  fix = known regression to fix during the merge
cd "$(git rev-parse --show-toplevel)" || exit 2
MODE=${1:-all}; pass=0; fail=0
check(){ local stage=$1 area=$2 name=$3 cmd=$4
  [[ $MODE != all && $MODE != $stage ]] && return
  if out=$(bash -c "$cmd" 2>&1); then pass=$((pass+1)); printf "PASS %-4s %-9s %s\n" "$stage" "$area" "$name"
  else fail=$((fail+1)); printf "FAIL %-4s %-9s %s\n" "$stage" "$area" "$name"; [[ -n $out ]] && printf "%s\n" "$out" | head -5; fi; }
