check now backend 'Worker never imports mongoose directly (runtime crash)' 'test -z "$(git grep -l -E "from ['"'"'\"]mongoose['"'"'\"]|require\\(['"'"'\"]mongoose" -- apps/worker/src | grep -v -x apps/worker/src/app/ai-settings/dal/ai-settings.entity.ts)"'
check now dashboard 'Settings routes render SettingsPage (positive)' 'for k in SETTINGS SETTINGS_ACCOUNT SETTINGS_ORGANIZATION SETTINGS_TEAM; do git grep -h -A1 -E "path: ROUTES\.${k}," -- apps/dashboard/src/main.tsx | grep -q -F '"'"'element: <SettingsPage />'"'"' || exit 1; done'
check post dashboard 'auth-side-banner uses no unimported IS_ENTERPRISE' '! git grep -q -w IS_ENTERPRISE -- apps/dashboard/src/components/auth/auth-side-banner.tsx'
check post dashboard 'Shim useAuth exposes currentUser (Settings > Team)' 'git grep -A12 -F '"'"'return {'"'"' -- apps/dashboard/src/utils/self-hosted/use-auth.ts | grep -q -w currentUser'
check post dashboard 'Upstream cloud-only AI flag left as upstream' 'git grep -q -F '"'"'export const IS_AI_FEATURES_ENABLED = IS_CLOUD;'"'"' -- apps/dashboard/src/config/index.ts'
check now tree 'No conflict markers anywhere' '! git grep -n -E '"'"'^(<<<<<<<|>>>>>>>) '"'"' -- . '"'"':!*.md'"'"''
check now tree 'Dashboard flag trip-wire: every IS_* flag user imports it' 'for flag in IS_ENTERPRISE IS_SELF_HOSTED IS_SELF_HOSTED_CE IS_SELF_HOSTED_EE IS_CLOUD; do for f in $(git grep -l -w $flag -- apps/dashboard/src '"'"':!apps/dashboard/src/config/index.ts'"'"'); do perl -0e '"'"'my $flag=shift; local $/; my $s=<>; $s=~s{/\*.*?\*/}{}gs; $s=~s{//[^\n]*}{}g; exit 0 unless $s=~/\b$flag\b/; exit($s=~/import\s*(type\s*)?\{[^}]*\b$flag\b[^}]*\}\s*from/s ? 0 : 1)'"'"' $flag "$f" || { echo "  $flag not imported: $f"; exit 1; }; done; done'
echo "---"; echo "pass=$pass fail=$fail"; exit $fail
